        );

        assertEquals(1, r.getId());
        assertEquals(101, r.getRoomNumber());
        assertEquals("João Silva", r.getGuestName());
        assertEquals(2, r.getNights());
        assertEquals(ReservationStatus.PENDING, r.getStatus());
