    void testHighSeasonPricing() {
        Reservation r = reservationService.createReservation(
            101, "Maria", "maria@example.com", "11122233344",
            LocalDate.of(2027, 7, 10),
            LocalDate.of(2027, 7, 12),
            2, RatePlan.STANDARD
        );

